Below is an example of a C function that iterates over the two‐dimensional rxdataF array and prints its integer values. In this example the number of rows is ru->nb_rx and the number of elements in each row is computed as

  NUMBER_RX_BUFFERS × fp->symbols_per_slot × fp->ofdm_symbol_size.

You may want to adjust the printing format (or limit the amount printed) if the arrays are very large.

--------------------------------------------------
/* Example code to print ru->common.rxdataF */

#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>

/* Assuming these are defined elsewhere in your project */
#define NUMBER_RX_BUFFERS  /* set appropriate number, e.g.: */ 1 

/* Dummy definitions of the structures for illustration.
   Replace or include the correct headers for your project. */
typedef struct {
    int32_t **rxdataF;
} common_struct;

typedef struct {
    int nb_rx;       // number of receiver antennas/branches
    common_struct common;
} RU;

typedef struct {
    int symbols_per_slot;
    int ofdm_symbol_size; 
} frame_parms_t;

/* Function to print the rxdataF array.
   ru  : Pointer to the RU structure that contains rxdataF.
   fp  : Pointer to the frame parameters structure.
*/
void print_rxdataF(RU *ru, frame_parms_t *fp) {
    if (ru == NULL || fp == NULL || ru->common.rxdataF == NULL) {
        printf("Invalid input pointer(s).\n");
        return;
    }

    /* Compute number of int32_t elements in each rxdataF row */
    int num_elements = NUMBER_RX_BUFFERS * fp->symbols_per_slot * fp->ofdm_symbol_size;

    for (int i = 0; i < ru->nb_rx; i++) {
        if (ru->common.rxdataF[i] == NULL) {
            printf("rxdataF[%d] is NULL.\n", i);
            continue;
        }

        printf("rxdataF[%d]:\n", i);
        for (int j = 0; j < num_elements; j++) {
            printf("%d ", ru->common.rxdataF[i][j]);

            /* Optionally, add a newline every ofdm_symbol_size elements,
               so that one OFDM symbol is printed in one line */
            if ((j + 1) % fp->ofdm_symbol_size == 0)
                printf("\n");
        }
        printf("\n");
    }
}

/* Example main function to illustrate usage of print_rxdataF */
int main(void) {
    /* Set up example frame parameters.
       You should fill in the actual values as per your requirements. */
    frame_parms_t fp = {
        .symbols_per_slot = 14,
        .ofdm_symbol_size = 1024
    };

    /* Set up an example RU structure.
       For this example assume ru->nb_rx = 2. */
    RU ru;
    ru.nb_rx = 2;

    /* Allocate memory for common.rxdataF (an array of pointers for each rx branch) */
    ru.common.rxdataF = (int32_t **)malloc(ru.nb_rx * sizeof(int32_t *));
    if (ru.common.rxdataF == NULL) {
        perror("malloc failed");
        return EXIT_FAILURE;
    }

    int num_elements = NUMBER_RX_BUFFERS * fp.symbols_per_slot * fp.ofdm_symbol_size;
    for (int i = 0; i < ru.nb_rx; i++) {
        /* Allocate and clear memory for each row.
           Here we mimic malloc16_clear by using calloc. 
           In your actual code, replace this with malloc16_clear if needed.
         */
        ru.common.rxdataF[i] = (int32_t *)calloc(num_elements, sizeof(int32_t));
        if (ru.common.rxdataF[i] == NULL) {
            perror("calloc failed");
            return EXIT_FAILURE;
        }

        /* For demonstration, fill the array with some example values.
           For instance, we fill it with the value (i*1000 + j).
         */
        for (int j = 0; j < num_elements; j++) {
            ru.common.rxdataF[i][j] = i * 1000 + j;
        }
    }

    /* Now call the function to print rxdataF */
    print_rxdataF(&ru, &fp);

    /* Free allocated memory */
    for (int i = 0; i < ru.nb_rx; i++) {
        free(ru.common.rxdataF[i]);
    }
    free(ru.common.rxdataF);

    return 0;
}

--------------------------------------------------

Explanation:

1. The function print_rxdataF takes a pointer to the RU structure and a pointer to the frame parameters structure.
2. It computes the number of elements per row using NUMBER_RX_BUFFERS, fp->symbols_per_slot, and fp->ofdm_symbol_size.
3. It iterates over the rxdataF array for each receiver and then prints each element. In this example, we add a newline after every OFDM symbol's worth of samples.
4. The main() function demonstrates how to allocate, initialize, and then print the rxdataF variable.

Make sure to adapt the code (especially the memory allocation functions and the macro definition for NUMBER_RX_BUFFERS) to fit your project’s actual definitions and requirements.

