import React, { useState, useEffect } from "react";
import axios from "axios";
import "./App.css";

function App() {
  const [todos, setTodos] = useState([]);
  const [description, setDescription] = useState("");
  const [editingId, setEditingId] = useState(null);
  const [editingDescription, setEditingDescription] = useState("");

  // Fetch todos from the server
  useEffect(() => {
    fetchTodos();
  }, []);

  const fetchTodos = async () => {
    try {
      const res = await axios.get("http://localhost:5000/todos");
      setTodos(res.data);
    } catch (error) {
      console.error("Error fetching todos:", error);
    }
  };

  const addTodo = async (e) => {
    e.preventDefault();
    try {
      const res = await axios.post("http://localhost:5000/todos", {
        description,
      });
      setTodos([...todos, res.data]);
      setDescription("");
    } catch (error) {
      console.error("Error adding todo:", error);
    }
  };

  const deleteTodo = async (id) => {
    try {
      await axios.delete(`http://localhost:5000/todos/${id}`);
      setTodos(todos.filter((todo) => todo.todo_id !== id));
    } catch (error) {
      console.error("Error deleting todo:", error);
    }
  };

  const startEditing = (todo) => {
    setEditingId(todo.todo_id);
    setEditingDescription(todo.description);
  };

  const updateTodo = async (e) => {
    e.preventDefault();
    try {
      await axios.put(`http://localhost:5000/todos/${editingId}`, {
        description: editingDescription,
      });
      setTodos(
        todos.map((todo) =>
          todo.todo_id === editingId
            ? { ...todo, description: editingDescription }
            : todo
        )
      );
      setEditingId(null);
      setEditingDescription("");
    } catch (error) {
      console.error("Error updating todo:", error);
    }
  };

  return (
    <div className="App">
      <h1>PERN Stack Todo List</h1>
      <form onSubmit={addTodo}>
        <input
          type="text"
          placeholder="Add Todo"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
        />
        <button type="submit">Add</button>
      </form>

      <ul>
        {todos.map((todo) => (
          <li key={todo.todo_id}>
            {editingId === todo.todo_id ? (
              <form onSubmit={updateTodo}>
                <input
                  type="text"
                  value={editingDescription}
                  onChange={(e) => setEditingDescription(e.target.value)}
                />
                <button type="submit">Update</button>
                <button type="button" onClick={() => setEditingId(null)}>
                  Cancel
                </button>
              </form>
            ) : (
              <div>
                <span>{todo.description}</span>
                <button onClick={() => startEditing(todo)}>Edit</button>
                <button onClick={() => deleteTodo(todo.todo_id)}>Delete</button>
              </div>
            )}
          </li>
        ))}
      </ul>
    </div>
  );
}

export default App;
------------------------------------------------

